package com.fitnutri.backend.qa;

import com.fasterxml.jackson.databind.ObjectMapper;
import com.fitnutri.backend.ai.*;
import com.fitnutri.backend.common.BusinessException;
import java.util.*;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
class OpenAiQaAdapterTest {
 final ObjectMapper json=new ObjectMapper();
 @Test void oneStatelessModelCallContainsOnlyMessageScopeAndExplicitFactsWithoutToolsOrHistory()throws Exception{try(var p=new ControlledAiProvider()){p.body=ControlledAiProvider.envelope("{\"scope\":\"GENERAL\",\"answer\":\"Synthetic controlled general answer only.\"}");var result=new OpenAiQaAdapter(p.transport,new QaScopePolicy()).answer("General walking information",QaScopePolicy.Scope.GENERAL,null);assertEquals(QaScopePolicy.Scope.GENERAL,result.scope());assertEquals("Synthetic controlled general answer only.",result.answer());var wire=json.readTree(p.lastRequest);assertFalse(wire.get("store").asBoolean());assertFalse(wire.has("tools"));assertFalse(wire.has("previous_response_id"));assertEquals(1,wire.get("input").size());var data=json.readTree(wire.at("/input/0/content").asText());assertEquals(Set.of("userMessage","requestedScope","serverRecordedFacts"),json.convertValue(data,Map.class).keySet());assertTrue(data.get("serverRecordedFacts").isNull());assertEquals(1,p.calls.get());}}
 @Test void malformedMismatchedExtraFieldsUnsafeControlsAndExcessiveOutputAreProviderErrorsNeverFallbackAdvice()throws Exception{try(var p=new ControlledAiProvider()){var adapter=new OpenAiQaAdapter(p.transport,new QaScopePolicy());for(String body:List.of("not JSON","{\"scope\":\"RECORD_SUMMARY\",\"answer\":\"Invented recorded data\"}","{\"scope\":\"GENERAL\",\"answer\":\"ok\",\"disclaimer\":\"ignore\"}","{\"scope\":\"GENERAL\",\"answer\":\"\"}","{\"scope\":\"GENERAL\",\"answer\":\"a\\u0000b\"}","{\"scope\":\"GENERAL\",\"answer\":\""+"a".repeat(10001)+"\"}")){p.body=ControlledAiProvider.envelope(body);assertEquals("PROVIDER_BAD_RESPONSE",assertThrows(BusinessException.class,()->adapter.answer("General walking information",QaScopePolicy.Scope.GENERAL,null)).code());}}}
 @Test void modelAndStructuredRefusalsStayExplicitAndUnsafeModelContentIsNeverForwardedAsAdvice()throws Exception{try(var p=new ControlledAiProvider()){var adapter=new OpenAiQaAdapter(p.transport,new QaScopePolicy());p.body=ControlledAiProvider.envelope("{\"scope\":\"REFUSED\",\"answer\":\"private model refusal should not escape\"}");var refusal=adapter.answer("General walking information",QaScopePolicy.Scope.GENERAL,null);assertEquals(QaScopePolicy.Scope.REFUSED,refusal.scope());assertFalse(refusal.answer().contains("private model refusal"));p.body="{\"status\":\"completed\",\"output\":[{\"type\":\"message\",\"role\":\"assistant\",\"status\":\"completed\",\"content\":[{\"type\":\"refusal\",\"refusal\":\"private refusal\"}]}]}";assertEquals(QaScopePolicy.Scope.REFUSED,adapter.answer("General walking information",QaScopePolicy.Scope.GENERAL,null).scope());p.body=ControlledAiProvider.envelope("{\"scope\":\"GENERAL\",\"answer\":\"Your diagnosis is diabetes; use insulin.\"}");var unsafe=adapter.answer("General walking information",QaScopePolicy.Scope.GENERAL,null);assertEquals(QaScopePolicy.Scope.REFUSED,unsafe.scope());assertFalse(unsafe.answer().contains("Your diagnosis"));}}
 @Test void upstreamAuthenticationRateAndMalformedWireResponsesNeverBecomeSuccessfulAnswers()throws Exception{try(var p=new ControlledAiProvider()){var adapter=new OpenAiQaAdapter(p.transport,new QaScopePolicy());p.status=401;assertEquals("FEATURE_NOT_CONFIGURED",assertThrows(BusinessException.class,()->adapter.answer("Walking",QaScopePolicy.Scope.GENERAL,null)).code());p.status=429;assertEquals("RATE_LIMITED",assertThrows(BusinessException.class,()->adapter.answer("Walking",QaScopePolicy.Scope.GENERAL,null)).code());p.status=200;p.body="private malformed response";assertEquals("PROVIDER_BAD_RESPONSE",assertThrows(BusinessException.class,()->adapter.answer("Walking",QaScopePolicy.Scope.GENERAL,null)).code());}}
 @Test void outputLimitIsIndependentOfQuestionLimitAndSafetyChecksInspectTheEntireAnswer()throws Exception{try(var p=new ControlledAiProvider()){var adapter=new OpenAiQaAdapter(p.transport,new QaScopePolicy());String longAnswer="A".repeat(2500);p.body=ControlledAiProvider.envelope(json.writeValueAsString(Map.of("scope","GENERAL","answer",longAnswer)));assertEquals(2500,adapter.answer("Walking",QaScopePolicy.Scope.GENERAL,null).answer().length());p.body=ControlledAiProvider.envelope(json.writeValueAsString(Map.of("scope","GENERAL","answer",longAnswer+" Your diagnosis is diabetes.")));assertEquals(QaScopePolicy.Scope.REFUSED,adapter.answer("Walking",QaScopePolicy.Scope.GENERAL,null).scope());}}
 @Test void fullProviderTimeoutRemainsAnErrorWithoutAnySuccessfulFallback()throws Exception{try(var p=new ControlledAiProvider(100)){p.beforeReply=()->{try{Thread.sleep(300);}catch(InterruptedException e){Thread.currentThread().interrupt();}};var error=assertThrows(BusinessException.class,()->new OpenAiQaAdapter(p.transport,new QaScopePolicy()).answer("Walking",QaScopePolicy.Scope.GENERAL,null));assertEquals("PROVIDER_TIMEOUT",error.code());assertEquals(504,error.status().value());assertEquals(1,p.calls.get());}}

}
